lel":"u","return_type":"pg_catalog.bool","returns_set":false,"rows":0,"security":true,"settings":["search_path=pg_catalog"],"strict":false,"volatility":"v"},{"argument_names":["model_name","n","verb"],"body":"377d6e6952533e1c03562cd940c5e3e5a9171221da8197eeea982c3cbcf70409","cost":100,"default_count":0,"identity":"platform_private.worker_row_capabilities(pg_catalog.text,pg_catalog.jsonb,pg_catalog.text)","language":"plpgsql","leakproof":false,"owner":"wa_schema_owner","parallel":"u","return_type":"pg_catalog.bool","returns_set":false,"rows":0,"security":false,"settings":["search_path=pg_catalog"],"strict":false,"volatility":"v"},{"argument_names":["model_name","n"],"body":"3dc2abca95d1692a4a14fc8232037b43488abf85c626bce79f49010b0d12f47c","cost":100,"default_count":0,"identity":"platform_private.worker_source_claim_valid(pg_catalog.text,pg_catalog.jsonb)","language":"plpgsql","leakproof":false,"owner":"wa_track_verifier","parallel":"u","return_type":"pg_catalog.bool","returns_set":false,"rows":0,"security":true,"settings":["search_path=pg_catalog"],"strict":false,"volatility":"v"},{"argument_names":["model_name","source_id"],"body":"8052c5722e1c719ed9223f70886bc9875f0e0054d4547f837b10540756eb24f0","cost":100,"default_count":0,"identity":"platform_private.worker_source_row_valid(pg_catalog.text,pg_catalog.text)","language":"plpgsql","leakproof":false,"owner":"wa_track_verifier","parallel":"u","return_type":"pg_catalog.bool","returns_set":false,"rows":0,"security":true,"settings":["search_path=pg_catalog"],"strict":false,"volatility":"v"},{"argument_names":["model_name","row_value","verb"],"body":"3e291feedebe4e865f852b06ef9f57435989e7293df1362477fb844f04d03db7","cost":100,"default_count":0,"identity":"platform_private.worker_track_allowed(pg_catalog.text,pg_catalog.jsonb,pg_catalog.text)","language":"plpgsql","leakproof":false,"owner":"wa_track_verifier","parallel":"u","return_type":"pg_catalog.bool","returns_set":false,"rows":0,"security":true,"settings":["search_path=pg_catalog"],"strict":false,"volatility":"v"}]'::jsonb) e(identity text,owner text,body text,security boolean,strict boolean,volatility text,parallel text,language text,return_type text,returns_set boolean,settings jsonb,argument_names jsonb,default_count integer,cost real,rows real,leakproof boolean) LEFT JOIN pg_proc p ON p.oid=to_regprocedure(e.identity) LEFT JOIN pg_language l ON l.oid=p.prolang WHERE p.oid IS NULL OR p.prokind<>'f' OR pg_get_userbyid(p.proowner) IS DISTINCT FROM e.owner OR encode(sha256(convert_to(p.prosrc,'UTF8')),'hex') IS DISTINCT FROM e.body OR p.prosecdef IS DISTINCT FROM e.security OR p.proisstrict IS DISTINCT FROM e.strict OR p.provolatile::text IS DISTINCT FROM e.volatility OR p.proparallel::text IS DISTINCT FROM e.parallel OR l.lanname IS DISTINCT FROM e.language OR p.prorettype IS DISTINCT FROM to_regtype(e.return_type) OR p.proretset IS DISTINCT FROM e.returns_set OR COALESCE(to_jsonb(p.proconfig),'[]'::jsonb) IS DISTINCT FROM e.settings OR COALESCE(to_jsonb(p.proargnames),'[]'::jsonb) IS DISTINCT FROM e.argument_names OR p.pronargdefaults IS DISTINCT FROM e.default_count OR p.procost IS DISTINCT FROM e.cost OR p.prorows IS DISTINCT FROM e.rows OR p.proleakproof IS DISTINCT FROM e.leakproof OR p.provariadic<>0 OR p.prosupport<>0 OR p.proallargtypes IS NOT NULL OR p.proargmodes IS NOT NULL)),false) AND COALESCE(((SELECT count(*) FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace WHERE n.nspname=ANY(ARRAY['app','platform','platform_private']) AND t.typtype='e')=29 AND NOT EXISTS(SELECT 1 FROM jsonb_to_recordset('[{"identity":"app.access_audit_action","labels":["file_read","file_download","message_read","thread_opened","video_joined","location_revealed","privacy_export_generated","privacy_erasure_started","privacy_erasure_completed","healthcare_policy_checked","healthcare_payload_redacted","healthcare_payload_blocked","admin_redacted_view","admin_blocked_view","processor_balance_read","payout_account_read","tax_profile_read","