,"comped","other"],"owner":"wa_schema_owner"},{"identity":"app.track_entitlement_grant_status","labels":["active","expired","revoked","suspended","consumed"],"owner":"wa_schema_owner"},{"identity":"app.track_entitlement_value_type","labels":["boolean","integer","decimal","percent_bps","money_cents","string","json"],"owner":"wa_schema_owner"},{"identity":"app.track_plan_status","labels":["draft","active","retired","archived"],"owner":"wa_schema_owner"},{"identity":"app.track_subscription_status","labels":["active","trialing","past_due","cancelled","expired","paused","incomplete","incomplete_expired"],"owner":"wa_schema_owner"},{"identity":"app.track_usage_event_type","labels":["job_application_submitted","candidate_search_boost_applied","application_view_tracked","buyer_fee_waived","priority_scheduling_used","professional_order_completed","professional_commission_applied","custom_domain_connected","live_streaming_used","internal_ad_campaign_created","other"],"owner":"wa_schema_owner"},{"identity":"app.track_usage_period","labels":["once","daily","monthly","yearly","lifetime","rolling_30_day"],"owner":"wa_schema_owner"},{"identity":"app.user_security_tier","labels":["standard","elevated","high_risk"],"owner":"wa_schema_owner"},{"identity":"platform.runtime_message_kind","labels":["event","command"],"owner":"wa_schema_owner"},{"identity":"platform.runtime_receipt_state","labels":["pending","committed","denied","unknown","fenced_noncommit"],"owner":"wa_schema_owner"},{"identity":"platform.runtime_reservation_state","labels":["active","committed","released","unknown"],"owner":"wa_schema_owner"},{"identity":"platform.runtime_work_state","labels":["pending","leased","completed","retry_wait","dead_letter","unknown"],"owner":"wa_schema_owner"}]'::jsonb) e(identity text,owner text,labels jsonb) LEFT JOIN pg_type t ON t.oid=to_regtype(e.identity) WHERE t.oid IS NULL OR t.typtype<>'e' OR pg_get_userbyid(t.typowner) IS DISTINCT FROM e.owner OR (SELECT jsonb_agg(x.enumlabel ORDER BY x.enumsortorder) FROM pg_enum x WHERE x.enumtypid=t.oid) IS DISTINCT FROM e.labels)),false) AND COALESCE((NOT EXISTS(SELECT 1 FROM pg_auth_members WHERE member=to_regrole('wa_schema_owner') AND roleid=ANY(ARRAY[to_regrole('wa_private_helper_owner'),to_regrole('wa_customer_verifier'),to_regrole('wa_track_verifier')])) AND NOT has_schema_privilege('wa_private_helper_owner','platform_private','CREATE') AND NOT has_schema_privilege('wa_customer_verifier','platform_private','CREATE') AND NOT has_schema_privilege('wa_track_verifier','platform_private','CREATE')),false)) THEN RAISE EXCEPTION 'catalog expression oracle prerequisite failed' USING ERRCODE='P0001'; END IF; END $wa_oracle_gate$;
